import (
	"crypto/rand"
	"golang.org/x/crypto/argon2"
)

func hashPassword(pw []byte) (salt, hash []byte) {
	salt = make([]byte, 16)
	_, _ = rand.Read(salt)
	// time=3, memory=64MB, threads=4, keyLen=32
	hash = argon2.IDKey(pw, salt, 3, 64*1024, 4, 32)
	return salt, hash
}

